<?php
declare(strict_types=1);
namespace Hostider\Services;
use Hostider\Core\{CanonicalJson,Config,Id};use Hostider\Core\Database\Database;use Hostider\Core\Http\HttpError;use Hostider\Core\Security\{Authorization,Crypto,Principal};use Hostider\Providers\Mock\DurableCpanel;use Hostider\Providers\Contract\Operation;
/** Resolves observed existing-resource mutations only; never repeats a provider mutation. */
final readonly class OperationReconciliation
{
    private Repository $repository;
    public function __construct(private Database $db,private Config $config){$this->repository=new Repository($db,$config);}
    private function authorize(string $id,string $customer,Principal $actor): void{if($this->config->environment!=='test'||!$actor->staff){throw new HttpError(403,'F3_TEST_ONLY');}(new Authorization())->require($actor,'services.reconcile',$customer,privileged:true,service:$id);}
    private function request(array $provider): array
    {
        $key=base64_decode($this->config->key,true);$json=(new Crypto($key))->decrypt($provider['request_encrypted'],'svc-operation:'.$provider['id']);if(!hash_equals($provider['request_fingerprint'],hash_hmac('sha256',$json,$key))){throw new HttpError(409,'RECONCILIATION_REQUEST_INTEGRITY');}return json_decode($json,true,64,JSON_THROW_ON_ERROR);
    }
    public function inspect(string $id,string $customer,Principal $actor,string $trace,?\Closure $reauthorize=null): array
    {
        $this->authorize($id,$customer,$actor);$service=$this->repository->find($id,$customer,false);if($service['status']!=='UNKNOWN'||$service['origin_environment']!=='test'||$service['imported']){throw new HttpError(409,'SERVICE_NOT_RECONCILABLE');}$provider=$this->db->execute("SELECT p.*,o.kind FROM svc_provider_operations p JOIN svc_operations o ON o.id=p.lifecycle_operation_id WHERE o.id=? AND o.status='UNKNOWN' AND o.kind<>'CREATE'",[$service['current_operation_id']])->fetch();if(!$provider||!$provider['server_id']){throw new HttpError(409,'PROVIDER_BINDING_MISSING');}$request=$this->request($provider);$adapter=new DurableCpanel($this->db,$this->config,$provider['server_id']);$result=$adapter->inspectAccount(new Operation(Id::uuid(),'inspectAccount',$request['resource_id']));$proof=$result->status==='SUCCESS'&&$result->externalResourceId!==null?$adapter->evidence($result->externalResourceId):null;
        return $this->db->transaction(function()use($id,$customer,$actor,$trace,$service,$provider,$proof,$reauthorize): array{
            if($reauthorize!==null){$reauthorize();}
            $this->authorize($id,$customer,$actor);$current=$this->repository->find($id,$customer);if($current['status']!=='UNKNOWN'||$current['version']!==$service['version']||$current['current_operation_id']!==$provider['lifecycle_operation_id']){throw new HttpError(409,'SERVICE_CHANGED_DURING_INSPECT');}$inspection=Id::uuid();$key=base64_decode($this->config->key,true);$json=CanonicalJson::encode(['proof'=>$proof,'provider_operation_id'=>$provider['id'],'request_fingerprint'=>$provider['request_fingerprint']]);$this->db->execute('INSERT INTO svc_inspections(id,service_id,operation_id,service_version,actor_id,found,evidence_encrypted,fingerprint,expires_at) VALUES (?,?,?,?,?,?,?,?,DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 5 MINUTE))',[$inspection,$id,$provider['lifecycle_operation_id'],$current['version'],$actor->actorId,$proof!==null?1:0,(new Crypto($key))->encrypt($json,'svc-inspection:'.$inspection),hash_hmac('sha256',$json,$key)]);$this->repository->event($current,'PROVIDER_INSPECTED',$actor,$trace);return ['inspection_id'=>$inspection,'found'=>$proof!==null,'decision'=>$proof!==null?'REVIEW_PROVIDER_STATE':'MANUAL_REVIEW_NO_RETRY'];
        });
    }
    public function resolve(string $id,string $customer,string $inspection,Principal $actor,string $trace): array
    {
        $this->authorize($id,$customer,$actor);$work=function()use($id,$customer,$inspection,$actor,$trace): array{
            $identity=$this->repository->find($id,$customer,false);$this->db->execute('SELECT id FROM orders WHERE id=? FOR UPDATE',[$identity['order_id']]);$service=$this->repository->find($id,$customer);$evidence=$this->db->execute('SELECT *,expires_at>UTC_TIMESTAMP(6) AS live FROM svc_inspections WHERE id=? AND service_id=?',[$inspection,$id])->fetch();if(!$evidence||$evidence['actor_id']!==$actor->actorId){throw new HttpError(403,'INSPECTION_SCOPE_MISMATCH');}if(!$evidence['found']||!$evidence['live']||$evidence['service_version']!==$service['version']||$service['status']!=='UNKNOWN'||$service['current_operation_id']!==$evidence['operation_id']){throw new HttpError(409,'INSPECTION_REQUIRES_MANUAL_REVIEW');}
            $op=$this->db->execute('SELECT * FROM svc_operations WHERE id=? FOR UPDATE',[$evidence['operation_id']])->fetch();$provider=$this->db->execute('SELECT * FROM svc_provider_operations WHERE lifecycle_operation_id=? FOR UPDATE',[$op['id']])->fetch();if($op['status']!=='UNKNOWN'||$provider['status']!=='UNKNOWN'){throw new HttpError(409,'OPERATION_NOT_UNKNOWN');}$request=$this->request($provider);$key=base64_decode($this->config->key,true);$json=(new Crypto($key))->decrypt($evidence['evidence_encrypted'],'svc-inspection:'.$inspection);if(!hash_equals($evidence['fingerprint'],hash_hmac('sha256',$json,$key))){throw new HttpError(409,'INSPECTION_INTEGRITY');}$data=json_decode($json,true,64,JSON_THROW_ON_ERROR);$proof=$data['proof'];$resource=$this->db->execute('SELECT external_id,server_id FROM svc_resources WHERE service_id=?',[$id])->fetch();
            if(!$proof||!$resource||$proof['id']!==$resource['external_id']||$proof['id']!==$request['resource_id']||$proof['server_id']!==$resource['server_id']||$proof['server_id']!==$provider['server_id']||$proof['service_id']!==$id||$data['provider_operation_id']!==$provider['id']||!hash_equals($provider['request_fingerprint'],$data['request_fingerprint'])){throw new HttpError(409,'INSPECTION_BINDING_MISMATCH');}
            $target=match($op['kind']){'RENEW'=>$proof['status'],'SUSPEND'=>'SUSPENDED','UNSUSPEND'=>'ACTIVE','TERMINATE'=>'TERMINATED','CHANGE_PACKAGE'=>$request['expected_status'],default=>throw new HttpError(409,'UNSUPPORTED_RECONCILIATION_KIND')};if($proof['status']!==$target||!in_array($target,['ACTIVE','SUSPENDED','TERMINATED'],true)){throw new HttpError(409,'OBSERVED_PROVIDER_STATE_REQUIRES_REVIEW');}
            if($op['kind']==='RENEW'){
                $renewal=$this->db->execute('SELECT * FROM svc_renewals WHERE operation_id=? FOR UPDATE',[$op['id']])->fetch();$period=$this->db->execute('SELECT * FROM svc_periods WHERE id=? FOR UPDATE',[$request['period_id']])->fetch();$previous=$this->db->execute('SELECT * FROM svc_periods WHERE id=? FOR UPDATE',[$request['previous_period_id']])->fetch();$end=\Hostider\Catalog\BillingCycle::next(new \DateTimeImmutable($request['expected_end'],new \DateTimeZone('UTC')),$request['cycle']['kind'],(int)$request['cycle']['interval_count'])->format('Y-m-d H:i:s.u');$bill=$this->db->execute('SELECT b.status,b.refund_status FROM orders o JOIN billing_request_states b ON b.request_id=o.payment_request_id WHERE o.id=? AND o.customer_id=? AND o.refund_status=\'NONE\' AND o.status<>\'CANCELLED\' FOR UPDATE',[$renewal['order_id'],$customer])->fetch();
                if(!$bill||$bill['status']!=='PAID'||$bill['refund_status']!=='NONE'||$period['status']!=='UNKNOWN'||$renewal['status']!=='UNKNOWN'||$period['id']!==$renewal['period_id']||$service['current_period_id']!==$previous['id']||$previous['ends_at']!==$request['expected_end']||$proof['ends_at']!==$end){throw new HttpError(409,'RENEWAL_RECONCILIATION_BINDING');}$proofJson=CanonicalJson::encode($proof);$periodEvidence=Id::uuid();$this->db->execute('INSERT INTO svc_period_evidence(id,period_id,operation_id,evidence_encrypted,fingerprint) VALUES (?,?,?,?,?)',[$periodEvidence,$period['id'],$op['id'],(new Crypto($key))->encrypt($proofJson,'svc-evidence:'.$periodEvidence),hash_hmac('sha256',$proofJson,$key)]);$this->db->execute("UPDATE svc_periods SET starts_at=?,ends_at=?,status='VERIFIED',version=version+1 WHERE id=?",[$request['expected_end'],$end,$period['id']]);$this->db->execute('UPDATE svc_services SET current_period_id=?,current_price_id=? WHERE id=?',[$period['id'],$period['price_id'],$id]);$this->db->execute("UPDATE svc_renewals SET status='VERIFIED' WHERE id=?",[$renewal['id']]);
            }elseif($op['kind']==='UNSUSPEND'){
                $entitlement=$this->db->execute("SELECT 1 FROM svc_periods p JOIN billing_request_states b ON b.request_id=p.billing_request_id WHERE p.id=? AND p.status='VERIFIED' AND p.ends_at>UTC_TIMESTAMP(6) AND b.status='PAID' AND b.refund_status='NONE' FOR UPDATE",[$service['current_period_id']])->fetchColumn();if(!$entitlement){throw new HttpError(409,'CURRENT_PAID_VERIFIED_PERIOD_REQUIRED');}
            }elseif($op['kind']==='CHANGE_PACKAGE'){
                if($proof['package_name']!==$request['provider_config']['package_name']){throw new HttpError(409,'PACKAGE_INSPECTION_MISMATCH');}(new PackageChanges($this->db,$this->config))->complete($service,$request['package_change_id'],true,true);
            }elseif($op['kind']==='TERMINATE'){
                if(!$this->db->execute("SELECT 1 FROM svc_cancellations WHERE service_id=? AND status='PENDING' AND execute_after<=UTC_TIMESTAMP(6) FOR UPDATE",[$id])->fetchColumn()){throw new HttpError(409,'TERMINATION_SAFEGUARD_NOT_PROVEN');}$this->db->execute("UPDATE svc_cancellations SET status='EXECUTED' WHERE service_id=? AND status='PENDING'",[$id]);$this->db->execute('UPDATE svc_services SET cancel_at=NULL WHERE id=?',[$id]);(new \Hostider\Hosting\Pools($this->db,$this->config))->releaseTerminatedService($id);
            }
            $resolution=Id::uuid();$this->db->execute('INSERT INTO svc_resolutions(id,service_id,operation_id,inspection_id,actor_id,trace_id) VALUES (?,?,?,?,?,?)',[$resolution,$id,$op['id'],$inspection,$actor->actorId,$trace]);$this->repository->transition($service,$target,$actor,$trace);return ['resolution_id'=>$resolution,'service_id'=>$id,'status'=>$target];
        };return $this->db->pdo->inTransaction()?$work():$this->db->transaction($work);
    }
}
